<script setup lang="ts">
/**
 * Links to a page's sections, the current marked (`design/components/table-of-contents.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table-of-contents.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import { agentMember, agentPress, jumpToSection, watchSections } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/table-of-contents.module.css'

export interface TableOfContentsItem {
  id: string
  label: string
  level?: 1 | 2
}

export interface TableOfContentsProps {
  /**
   * One link per section, in the page's order.
   */
  items: TableOfContentsItem[]
  /**
   * The landmark's name, drawn above the list ("On this page").
   */
  label: string
}

defineOptions({ name: 'TableOfContents', inheritAttrs: false })

const props = defineProps<TableOfContentsProps>()
const emit = defineEmits<{ currentChange: [id: string | null] }>()
const uid = useId()
const current = ref(null as string | null)
const nav = useTemplateRef<HTMLElement>('nav')
const labelId = computed(() => `${uid}-label`)
const groups = computed(() =>
  props.items.reduce(
    (groups, item, at) => {
      const parent = groups[groups.length - 1]
      if (item.level === 2 && parent !== undefined) parent.children.push({ item, at })
      else groups.push({ item, at, children: [] })
      return groups
    },
    [] as {
      item: TableOfContentsItem
      at: number
      children: { item: TableOfContentsItem; at: number }[]
    }[],
  ),
)
const currentAt = computed(() => props.items.findIndex((item) => item.id === current.value))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = watchSections(
    nav.value,
    props.items.map((item) => item.id),
    (id) => {
      if (id === current.value) return
      current.value = id
      emit('currentChange', id)
    },
  )
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
watch(() => props.items.map((item) => item.id).join(' '), effect1, { flush: 'post' })
onBeforeUnmount(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'TableOfContents',
    element: () => nav.value,
    state: () => ({
      current: current.value,
      items: props.items
        .filter((item, at) => props.items.findIndex((other) => other.id === item.id) === at)
        .map((item) => ({ id: item.id, label: item.label })),
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          agentPress(
            nav.value?.querySelectorAll('a')[props.items.findIndex((item) => item.id === value)],
          ),
      },
    },
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <nav ref="nav" :class="styles.nav" :aria-labelledby="labelId" data-member="table-of-contents">
    <!-- label -->
    <p :class="styles.label" :id="labelId">
      {{ label }}
    </p>
    <!-- list -->
    <ul :class="styles.list">
      <template v-for="group in groups" :key="`${group.at}:${group.item.id}`">
        <!-- item -->
        <li :class="styles.item">
          <!-- link -->
          <a
            :class="styles.link"
            :href="`#${group.item.id}`"
            :aria-current="group.at === currentAt ? 'location' : undefined"
            @click="jumpToSection(nav, group.item.id, $event)"
          >
            {{ group.item.label }}
          </a>
          <!-- sublist -->
          <ul v-if="group.children.length > 0" :class="styles.sublist">
            <template v-for="child in group.children" :key="`${child.at}:${child.item.id}`">
              <!-- item -->
              <li :class="styles.item">
                <!-- link -->
                <a
                  :class="styles.link"
                  :href="`#${child.item.id}`"
                  :aria-current="child.at === currentAt ? 'location' : undefined"
                  @click="jumpToSection(nav, child.item.id, $event)"
                >
                  {{ child.item.label }}
                </a>
              </li>
            </template>
          </ul>
        </li>
      </template>
    </ul>
  </nav>
</template>
